  "implementation": "import math
def solve(case):
    sentence_vectors = case['sentence_vectors']
    query_vector = case['query_vector']
    context_weight = case['context_weight']
    n = len(sentence_vectors)
    similarities = []
    # Compute cosine similarities
    for vec in sentence_vectors:
        dot = sum(a*b for a,b in zip(vec, query_vector))
        norm_vec = math.sqrt(sum(a*a for a in vec))
        norm_query = math.sqrt(sum(a*a for a in query_vector))
        if norm_vec == 0 or norm_query == 0:
            sim = 0.0
        else:
            sim = dot / (norm_vec * norm_query)
        similarities.append(sim)
    # Compute neighbor average and blend
    scores = []
    for i in range(n):
        own = similarities[i]
        neighbors = []
        if i > 0:
            neighbors.append(similarities[i-1])
        if i < n-1:
            neighbors.append(similarities[i+1])
        if neighbors:
            neighbor_avg = sum(neighbors) / len(neighbors)
        else:
            neighbor_avg = 0.0
        blended = (1 - context_weight) * own + context_weight * neighbor_avg
        scores.append(round(blended, 6))
    # Ranking: descending score, then ascending index
    indexed = [(scores[i], i) for i in range(n)]
    indexed.sort(key=lambda x: (-x[0], x[1]))
    ranking = [idx for _, idx in indexed]
    return {'ranking': ranking, 'scores': scores}
